import {finalData} from './final-data.js?v=20261028-geofinal';
import {finalLabs,labSlug,gradeFinalLab} from './final-labs.js?v=20261028-geofinal';
import {forestData,brazilPaths} from './cities-data.js?v=20261024-cities01';
